CREATE TABLE cmdb_ire_field_policies (tenant_id BIGINT UNSIGNED NOT NULL, class VARCHAR(30) NOT NULL DEFAULT '*', field_key VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, strategy ENUM('AUTHORITATIVE','PRIORITY','FRESHEST','FILL_EMPTY') NOT NULL DEFAULT 'PRIORITY', authoritative_source_id BIGINT UNSIGNED NULL, allow_manual_override BOOLEAN NOT NULL DEFAULT TRUE, version BIGINT UNSIGNED NOT NULL DEFAULT 1, updated_by BIGINT UNSIGNED NOT NULL, updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(tenant_id,class,field_key), KEY cmdb_ire_policy_authority(tenant_id,authoritative_source_id), CONSTRAINT cmdb_ire_policy_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT cmdb_ire_policy_source FOREIGN KEY(tenant_id,authoritative_source_id) REFERENCES cmdb_ire_sources(tenant_id,id), CONSTRAINT cmdb_ire_policy_user FOREIGN KEY(updated_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
